def lazyperclassproperty(fn):
    """
    A decorator that creates a lazy/cached class property. This ensures that each subclass or class instance has its own separate instance of the property, preventing overlap.

    Parameters:
        fn (function): The function to be wrapped by this decorator. It should take one argument which is the class itself.

    Returns:
        function: A new function that behaves as a lazy/cached class property.

    Example:
        To use this decorator, define a function and decorate it with @lazyperclassproperty. The decorated function will be called once per class or subclass to generate the property value, which is then cached for future calls within the same class hierarchy.

        ```python
        def my_property(cls):
            return some_expensive_computation()

        @lazyperclassproperty(my_property)
        def expensive_property(cls):
            pass
        ```
    """
    @classproperty
    def _lazyclassprop(cls):
        attr_name = '_%s_lazy_%s' % (cls.__name__, fn.__name__)
        if not hasattr(cls, attr_name):
            setattr(cls, attr_name, fn(cls))
        return getattr(cls, attr_name)

    return _lazyclassprop
