class ClassPropertyMeta(type):
    """
    A metaclass that allows properties of a class to be accessed and modified as if they were attributes. This is useful for defining read-only or write-once properties in a class. The `classproperty` decorator can be used to define such properties.

    Parameters:
        key (str): The name of the attribute being set.
        value: The value to assign to the attribute.

    Returns:
        None

    Example:
        To use this metaclass, you would typically subclass a class and apply the `classproperty` decorator to define properties that can be accessed or modified as if they were regular attributes. Here's an example:

        ```python
        from classproperty import classproperty

        class MyClass(metaclass=ClassPropertyMeta):
            _prop = None

            @classproperty
            def prop(cls):
                return cls._prop

            @prop.setter
            def prop(cls, value):
                if cls._prop is not None:
                    raise AttributeError("The property 'prop' can only be set once.")
                cls._prop = value

        # Usage
        obj = MyClass()
        obj.prop = 123  # This will work because it initializes the property
        print(obj.prop)  # Output: 123
        ```

    In this example, `MyClass` has a read-only or write-once property called `prop`. The metaclass `ClassPropertyMeta` ensures that the property can only be set once and raises an error if it is attempted to be changed after initialization.
    """

    def __setattr__(self, key, value):
        obj = self.__dict__.get(key, None)
        if type(obj) is classproperty:
            return obj.__set__(self, value)
        return super().__setattr__(key, value)
