class InvalidPattern:
    _fmt = 'Invalid pattern(s) found. %(msg)s'
    def __init__(self, msg):
        self.msg = msg

    def __str__(self):
        s = self._format()
        if isinstance(s, unicode):
            s = s.encode('utf8')
        else:
            # __str__ must return a str.
            s = str(s)
        return s

    def _format(self):
        """
        Formats the error message according to the predefined format or returns a default error string if the format is not defined or there's an issue with formatting.

        Parameters:
            None

        Returns:
            str: The formatted error string which includes the provided message if set. If no specific format is defined or if there's an issue with formatting, a default error string is returned.
        """
        return self._fmt % {'msg': self.msg}
